package com.estoqueinteligente.auth;
import java.util.Locale;import org.springframework.security.authentication.*;import org.springframework.security.core.AuthenticationException;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.estoqueinteligente.common.BusinessException;
@Service public class AuthService{private final AuthenticationManager authenticationManager;private final UserRepository repository;private final PasswordEncoder encoder;private final JwtService jwt;private final CustomUserDetailsService userDetails;public AuthService(AuthenticationManager authenticationManager,UserRepository repository,PasswordEncoder encoder,JwtService jwt,CustomUserDetailsService userDetails){this.authenticationManager=authenticationManager;this.repository=repository;this.encoder=encoder;this.jwt=jwt;this.userDetails=userDetails;}@Transactional(readOnly=true)public AuthResponse login(LoginRequest request){String email=normalizeEmail(request.getEmail());try{authenticationManager.authenticate(new UsernamePasswordAuthenticationToken(email,request.getPassword()));}catch(AuthenticationException e){throw new AuthenticationFailedException("E-mail ou senha inválidos");}AppUser user=repository.findByEmailIgnoreCase(email).orElseThrow(()->new AuthenticationFailedException("E-mail ou senha inválidos"));if(!user.isActive())throw new AuthenticationFailedException("Usuário inativo");UserDetails details=userDetails.loadUserByUsername(email);return new AuthResponse(jwt.generateToken(details),user);}@Transactional public UserResponse register(RegisterRequest request){String email=normalizeEmail(request.getEmail());if(repository.existsByEmailIgnoreCase(email))throw new BusinessException("E-mail já cadastrado");AppUser user=new AppUser();user.setName(request.getName().trim());user.setEmail(email);user.setPassword(encoder.encode(request.getPassword()));if(request.getRole()!=UserRole.USER)throw new BusinessException("O cadastro público permite apenas o perfil USER");user.setRole(UserRole.USER);user.setActive(true);return new UserResponse(repository.save(user));}private String normalizeEmail(String email){return email.trim().toLowerCase(Locale.ROOT);}}
